package main

import (
 "bufio"
 "context"
 "encoding/json"
 "fmt"
 "net/http"
 "os"
 "time"
 "stackd/compute/docker"
 "stackd/compute/network"
 "stackd/compute/ec2"
)

func main() {
 ctx:=context.Background()
 d,e:=docker.New(ctx,docker.Config{}); if e!=nil {panic(e)}; defer d.Close()
 b,_:=network.NewBridges(d)
 var gm *ec2.GuestNetworkManager
 s:=bufio.NewScanner(os.Stdin)
 for s.Scan() {
  var v struct { Op,Name,Peer,StateDirectory string; Spec network.Specification; Bridge network.Bridge; TimeoutMillis int; CallbackApply bool }
  var result any
  e=json.Unmarshal(s.Bytes(),&v)
  if e==nil {
   ctx,cancel:=context.WithTimeout(ctx,30*time.Second); if v.TimeoutMillis>0 {cancel();ctx,cancel=context.WithTimeout(context.Background(),time.Duration(v.TimeoutMillis)*time.Millisecond)};defer cancel()
   switch v.Op {
   case "bridge": e=b.WithBridge(ctx,v.Spec,func(n network.Bridge)error{result=n;if v.CallbackApply {return b.ApplyPolicy(ctx,v.Name,v.Spec,v.Spec.Policy,v.Peer,network.Options{Callback:v.Spec.Gateway.String()+":8181",Guest:true,PublicOwner:v.StateDirectory},n)};return nil})
   case "apply": e=b.ApplyPolicy(ctx,v.Name,v.Spec,v.Spec.Policy,v.Peer,network.Options{Callback:v.Spec.Gateway.String()+":8181",Guest:true,PublicOwner:v.StateDirectory},v.Bridge)
   case "remove": e=b.RemovePolicy(ctx,v.Name,v.StateDirectory)
   case "release": e=b.Release(ctx,v.Spec.NetworkID)
   case "guest":
    if gm==nil {gm,e=ec2.NewGuestNetworks(ctx,ec2.GuestNetworkConfig{Docker:d,Bridges:b,StateDirectory:v.StateDirectory,DNSMasqBinary:"/usr/sbin/dnsmasq"})}
    if e==nil {_,e=gm.Prepare(ctx,v.Name,v.Spec,http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){fmt.Fprint(w,"metadata-private-ok")}))}
   case "guest-remove": e=gm.Remove(ctx,v.Name,v.Spec)
   default: e=fmt.Errorf("unknown command")
   }
  }
  msg:=map[string]any{"result":result}; if e!=nil {msg["error"]=e.Error()}; json.NewEncoder(os.Stdout).Encode(msg)
 }
}
